mapper.insert:
INSERT INTO HH_USER(
	UPDATE_DATE
	, ENABLED
	, ID 
	, ROLE
	, NICKNAME 
	, BIRTHDAY
	, IMAGE  
	, PW_CHECK
) VALUES (
	DATETIME('NOW','LOCALTIME')
	, #{enabled, typeHandler=com.utime.household.common.handler.BooleanTypeHandler}
	, #{id}
	, #{role}
	, #{nickname}
	, #{birthday}
	, #{image} 
	, #{pwCheck}
)

mapper.update:
UPDATE HH_USER SET
	UPDATE_DATE = DATETIME('NOW','LOCALTIME')
	, PW = #{pw, typeHandler=com.utime.household.user.typeHandler.PasswordEncoderTypeHandler}
WHERE NO = #{userNo}

UPDATE HH_USER SET
	UPDATE_DATE = DATETIME('NOW','LOCALTIME')
	, ENABLED = #{enabled, typeHandler=com.utime.household.common.handler.BooleanTypeHandler}
	, NICKNAME = #{nickname} 
	, IMAGE = #{image}  
	, PW_CHECK = #{pwCheck}
WHERE NO = #{userNo}

mapper.select:
SELECT 

FROM HH_USER
WHERE 1=1
	AND ENABLED = 'Y'

	AND ID = #{id}


	AND BIRTHDAY = #{birthday}

	AND PW_CHECK = #{pwCheck}

		SELECT COALESCE(
		    (	SELECT
		    		NO
		    	FROM HH_USER
		    	WHERE 1=1
		    		AND ENABLED = 'Y'
		    		AND ID = #{id}
		    		AND PW = #{pw, typeHandler=com.utime.household.user.typeHandler.PasswordEncoderTypeHandler}
    		), 
    	-1 ) AS NO;
